function syncSoundBtn(){if(!soundBtn)return;const on=soundOn();soundBtn.setAttribute('aria-pressed',String(on));soundBtn.setAttribute('aria-label',on?'Sound on. Tap to mute.':'Sound off. Tap to turn on.');soundBtn.title=on?'Sound on':'Sound off';soundBtn.classList.toggle('on',on);soundBtn.innerHTML=on?SPEAKER_ON:SPEAKER_OFF;}
