// Seats also live in localStorage per room so a closed tab can rejoin. ?new=1 skips this for test players.
function seatKey(code){return `oops-seat-${String(code||'').toUpperCase()}`;}
function saveSeat(a,name){try{sessionStorage.setItem('badbets',JSON.stringify(a));}catch{}try{if(a?.code){const old=storedSeat(a.code);localStorage.setItem(seatKey(a.code),JSON.stringify({code:a.code,token:a.token,name:name||(old?.token===a.token?old.name:''),savedAt:Date.now()}));}}catch{}}
// Keep phones from sleeping mid-game. Unsupported browsers just skip it.
let wakeLock=null;async function keepAwake(){try{if(!('wakeLock' in navigator)||document.hidden||(wakeLock&&!wakeLock.released))return;wakeLock=await navigator.wakeLock.request('screen');}catch{}}
function releaseWake(){try{wakeLock?.release?.().catch?.(()=>{});}catch{}wakeLock=null;}
function forgetSeat(code){try{if(code)localStorage.removeItem(seatKey(code));}catch{}}
function storedSeat(code){try{const a=JSON.parse(localStorage.getItem(seatKey(code))||'null');return a?.code&&a?.token&&Date.now()-(a.savedAt||0)<43200000?a:null;}catch{return null;}}
function latestSeat(){try{let best=null;for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k?.startsWith('oops-seat-')){const a=storedSeat(k.slice(10));if(a&&(!best||a.savedAt>best.savedAt))best=a;}}return best;}catch{return null;}}
let auth=savedAuth,state=null,events=null,pollTimer=null,pollVersion=0,lastState='',renderKey='',drawing=null;const titles={auction:'Bidding War',quips:'Bad Answers',shadow:'Shadowbox',rhythm:'Keep It Going',brain:'Same Brain?',number:'Ballpark',draft:'Fantasy Draft',draw:'Drawn Into Trouble',imposter:'Imposter',finale:'One More Round'};
