let qrCache={url:'',svg:''},showQr=false,ratedKey='';function inviteQr(code){const url=`${inviteOrigin}?room=${code}`;if(qrCache.url!==url){let svg='';try{if(window.qrcode){const q=window.qrcode(0,'M');q.addData(url);q.make();svg=q.createSvgTag({cellSize:4,margin:2,scalable:true});}}catch{}qrCache={url,svg};}return qrCache.svg?`<div class="invite-qr" role="img" aria-label="QR code to join room ${code}">${qrCache.svg}<span>Scan to join</span></div>`:'';}
