function quickAuction(s,timer){const q=s.qa;if(!q)return '<p>Loading…</p>';const k=`${s.round}:${q.step}:${q.revision}`;if(qaKey.split(':').slice(0,2).join(':')!==`${s.round}:${q.step}`){qaPick=null;qaAmount=1;}qaKey=k;
 if(qaPick&&!q.cards.includes(qaPick))qaPick=null;qaAmount=Math.min(Math.max(1,qaAmount),q.max||1);const other=s.active.find(id=>id!==s.you),pos=POS[q.slot]||q.label;
 const status=q.done?`<div class="q-banner">You have your ${esc(pos)}. Waiting for ${esc(name(other))}…</div>`:q.mine?`<div class="q-banner">Locked: ${esc(q.mine.item)} for $${q.mine.amount}. ${q.submitted[other]?'Revealing…':`Waiting for ${esc(name(other))}…`}</div>`:`<div class="q-banner go">Pick a ${esc(pos)} and set your price</div>`;
 return `<div class="q-top"><span>Round ${q.step+1} of ${q.total} · ${esc(pos)}</span>${timer}</div><div class="q-budget"><span class="me">You $${q.budgets[s.you]}</span><span>${esc(name(other))} $${q.budgets[other]}</span></div>${q.last?`<p class="q-last${q.last.clash?' clash':''}">${esc(q.last.text)}</p>`:''}${status}
 <div class="q-cards">${q.cards.map((item,i)=>`<button type="button" class="q-card${qaPick===item?' picked':''}" data-action="qaPick:${i}" ${q.done||q.mine?'disabled':''}>${cardLabel({...s,game:'draft'},item,q.step)}</button>`).join('')}</div>
 ${q.done||q.mine?'':`<div class="q-bid"><div class="q-bid-row"><button type="button" class="secondary" data-action="qaAmt:-1" aria-label="Lower bid">−</button><strong>$${qaAmount}</strong><button type="button" class="secondary" data-action="qaAmt:1" aria-label="Raise bid">+</button></div><div class="q-bid-quick">${[5,10,20].filter(n=>n<=q.max).map(n=>`<button type="button" class="ghost" data-action="qaSet:${n}">$${n}</button>`).join('')}<button type="button" class="ghost" data-action="qaSet:${q.max}">Max $${q.max}</button></div>${btn(qaPick?`Lock ${esc(qaPick)} for $${qaAmount}`:'Pick a player first','qaLock','full',!qaPick)}<p class="micro">Same player as ${esc(name(other))}? Higher bid gets the player and the other picks again. Keep $1 for each position left.</p></div>`}${quickTray(s)}`;}
function quickFinish(s){const ready=s.qready||[],other=s.active.find(id=>id!==s.you),me=ready.includes(s.you);
 return `<div class="q-top"><span>Lineups locked</span></div>${quickTray(s)}<form id="pitchform" class="q-name"><label for="answer">Team name (optional)</label><div><input id="answer" maxlength="40" placeholder="Name your team"><button class="secondary">Save</button></div>${s.answers?.[s.you]?`<p class="micro">Saved: “${esc(s.answers[s.you])}”</p>`:''}</form><div class="grade-call"><p><b>Call your grade (optional).</b> What will the scout give you?</p><div class="row">${['A','B','C'].map(b=>btn(b==='C'?'C or worse':b,'callGrade:'+b,s.calls?.[s.you]===b?'selected':'secondary')).join('')}</div></div>${me?`<div class="q-banner">Ready. ${ready.includes(other)?'Grading…':`Waiting for ${esc(name(other))}…`}</div>`:btn('Ready: show results','quickReady','full q-ready')}<p class="micro">${ready.includes(other)&&!me?`${esc(name(other))} is ready.`:'Results show as soon as you are both ready.'}</p>`;}
function scoutCard(pid,r){const c=r.scout[pid],win=r.winners.includes(pid),called=c.call?(c.call===c.band?`<p class="scout-call hit">Called ${c.call==='C'?'C or worse':c.call}. Nailed it.</p>`:`<p class="scout-call">Called ${c.call==='C'?'C or worse':c.call}. Missed.</p>`):'';return `<div class="scout-card${win?' win':''}">${win?'<span class="scout-crown">Winner</span>':''}<div class="scout-head"><b>${name(pid)}</b>${s_votes(pid,r)}</div><div class="scout-grade"><span>${c.grade}</span><small>team ${c.score.toFixed(1)} · ${c.rank||`top ${c.top}%`}</small></div><p class="scout-report">${esc(c.report)}</p>${c.players.map(p=>`<div class="scout-row"><span class="pos">${esc(p.slot)}</span><span class="pl">${esc(p.name)}</span><span class="ovr">${p.ovr}</span></div>`).join('')}${called}${state.answers?.[pid]?`<p class="answer">“${esc(state.answers[pid])}”</p>`:''}</div>`;}
