function setupCanvas(saved){const c=document.querySelector('canvas'),ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#252332';ctx.lineWidth=5;ctx.lineCap='round';ctx.lineJoin='round';if(saved){const im=new Image();im.onload=()=>ctx.drawImage(im,0,0);im.src=saved;}let down=false;const point=e=>{const r=c.getBoundingClientRect();return [(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height];};c.onpointerdown=e=>{down=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));};c.onpointermove=e=>{if(down){ctx.lineTo(...point(e));ctx.stroke();}};c.onpointerup=c.onpointercancel=()=>{down=false;};}
async function handle(a){const [type,value]=a.split(':');if(type==='shareMoment'){beacon('share');shareMoment().catch(()=>toast('Could not make the card. Try again.'));return;}if(type==='lateJoin')return act({type,enabled:state.lateJoin?.on===false});if(type==='removeWaiting')return act({type,player:value});if(type==='callGrade')return act({type,band:value});if(type==='quickReady')return act({type});if(type==='qaPick'){qaPick=state.qa?.cards[Number(value)]||null;render();return;}if(type==='qaAmt'){qaAmount=Math.min(state.qa?.max||1,Math.max(1,qaAmount+Number(value)));render();return;}if(type==='qaSet'){qaAmount=Number(value);render();return;}if(type==='qaLock'){if(!qaPick)return;return act({type:'qbid',item:qaPick,amount:qaAmount});}if(type==='rematchNow')return act({type:'rematch',now:true});if(type==='audience')return act({type:'setAudience',audience:value});if(type==='shareCard'){beacon('share');shareCard().catch(()=>toast('Could not make the card. Try again.'));return;}if(type==='quickGame')return act({type:'quickSetup',game:value});if(type==='quickSport')return act({type:'quickSetup',sport:value});if(type==='finaleMode'){finaleUi.mode=value==='draw'?'draw':'answer';render();return;}if(type==='finalePick')return act({type,index:state.finale?.pick?.index,prompt:value});if(type==='finaleVote')return act({type,entry:value});if(type==='herdVote')return act({type,side:value});if(type==='finaleDraw'){finaleUi.autoSent=`${state.code}:${state.round}`;await act({type:'finaleEntry',value:document.querySelector('canvas').toDataURL()});return;}if(type==='qrToggle'){showQr=!showQr;render();return;}if(type==='rate'){if(!['fire','meh'].includes(value)||ratedKey===`${state.code}:${state.round}`)return;ratedKey=`${state.code}:${state.round}`;render();api({type:'rate',vote:value}).catch(()=>{});return;}if(type==='pot')return sendPot(['match','fold','allin','limit'].includes(value)?value:'raise',Number(value));if(type==='auctionRaise')return act({type,by:Number(value)||1,revision:state.auction.revision});if(type.startsWith('auction'))return act({type,revision:state.auction.revision});if(type==='largeMatchups')return act({type,enabled:!state.largeMatchups});if(type==='display'){window.open(`/display.html?room=${state.code}#${state.displayToken}`,'_blank','noopener');return;}if(type==='help')return help();if(type==='dateMode')return act({type:'configure',mode:'mixer',deck:'date'});if(type==='mode')return act({type:'mode',mode:value});if(type==='removeDisconnected')return act({type,player:value});if(type==='selectGame')return act({type,game:value});if(type==='categoryPick'||type==='categoryRandom')return act({type:'physicalCategory',revision:state.physical.revision,random:type==='categoryRandom',value:state.categories[Number(value)]});if(type==='practice'||type==='physicalStart'){try{await unlockBeat();await act({type:'physicalStart',practice:type==='practice',revision:state.physical.revision});}catch(e){toast('Sound could not start. Check browser audio permissions.');}return;}if(type==='physicalPlus'||type==='physicalMinus')return act({type:'physicalScore',player:value,delta:type==='physicalPlus'?1:-1,revision:state.physical.revision});if(type.startsWith('physical'))return act({type,revision:state.physical.revision});if(type==='toggleGame')return act({type,game:value});if(type==='themePick'){const [game,theme]=String(value||'').split('/');return act({type:'setTheme',game,theme});}if(type==='packToggle'){const on=state.packs||[];return act({type:'setPacks',packs:on.includes(value)?on.filter(x=>x!==value):[...on,value]});}if(type==='customRemove')return act({type:'removeCustom',index:Number(value)});if(type==='roundCount')return act({type,rounds:Number(value)});if(type==='banSetting')return act({type,enabled:!state.banEnabled});if(type==='banVote')return act({type,game:value});if(type==='banAbstain')return act({type:'banVote',game:null});if(type==='mixerChoice')return act({type:'mixerAnswer',value:state.options[Number(value)]});if(type==='mixerPass')return act({type:'mixerAnswer',pass:true});if(type==='mixerSpoken')return act({type:'mixerAnswer',value:'Sharing out loud'});if(type==='share'){const url=`${inviteOrigin}?room=${state.code}`;if(navigator.share){try{await navigator.share({title:'Oops, All In',text:`Join my game of Oops, All In. Room code ${state.code}`,url});}catch{}return;}try{await navigator.clipboard.writeText(url);toast('Invite link copied.');}catch{toast('Copy the invite address shown above.');}return;}if(type==='copy'){try{await navigator.clipboard.writeText(`${inviteOrigin}?room=${state.code}`);toast('Invite link copied.');}catch{toast('Copy the invite address shown above.');}return;}if(type==='test'){window.open(`${location.origin}?room=${state.code}&new=1`,'_blank','noopener');return;}if(type==='leave'){const dialog=showDialog(state.waiting?`<div class="channel-detail"><h2>Leave the line?</h2><p>You’ll lose your spot. You can join again with the room code.</p><button id="confirm-leave">Leave</button><button data-close class="ghost">Stay</button></div>`:`<div class="channel-detail"><h2>Leave the game?</h2><p>You can’t rejoin until the next lobby, and chips in this pot are lost.</p><button id="confirm-leave">Leave</button><button data-close class="ghost">Stay</button></div>`);dialog.querySelector('#confirm-leave').onclick=async()=>{dialog.close();try{await api({type:'leave'});exit();}catch(e){toast(e.message);}};return;}if(type==='download'){const text=`OOPS, ALL IN: SESSION RECAP\n\n${(state.awards||[]).length?`AWARDS\n${state.awards.map(a=>`${awardText(a)} (${a.line})`).join('\n')}\n\n`:''}${state.players.filter(p=>!p.left).sort((a,b)=>b.chips-a.chips).map(p=>`${p.name}: ${p.chips} chips`).join('\n')}\n\n${state.history.map(h=>`Round ${h.round}: ${titles[h.game]}\n${h.prompt}\n${h.detail}`).join('\n\n')}`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='oops-all-in-recap.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(type==='clear'){drawing=null;setupCanvas(null);return;}if(type==='drawing'){await act({type:'submit',promptVersion:state.promptVersion,value:document.querySelector('canvas').toDataURL()});return;}if(type==='stake')return act({type,amount:Number(value)});if(type==='stay'||type==='fold')return act({type:'entry',stay:type==='stay'});if(type==='bet')return act({type,team:Number(value)});if(type==='pick')return act({type,item:state.cards[Number(value)]});if(type==='vote')return act({type,player:value});return act({type});}
function updateClock(){if(state){const c=clockCue(state,Date.now(),clockMemo);if(c)play(c,{buzz:false});}const t=document.querySelector('.timer');if(t&&state?.deadline)t.textContent=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));{const m=state?.finale?.mine,c=document.querySelector('canvas'),k=`${state?.code}:${state?.round}`;if(state?.phase==='finalePlay'&&m?.prompt?.mode==='draw'&&!m.submitted&&c&&state.deadline&&state.deadline-Date.now()<1800&&finaleUi.autoSent!==k){finaleUi.autoSent=k;act({type:'finaleEntry',value:c.toDataURL()});}}const v=document.querySelector('[data-veto-until]');if(v){const left=Math.ceil((Number(v.dataset.vetoUntil)-Date.now())/1000);if(left<=0&&state?.veto?.open){state.veto.open=false;render();}else{const n=v.querySelector('.veto-count');if(n)n.textContent=Math.max(0,left);}}}
// Rolled theme with a short veto window. Each player has one veto for the whole session.
function vetoPanel(s){const v=s.veto,left=v.left?'1 veto left':'Veto used';let action='';
 if(v.done)action=`<p class="veto-news" role="status"><b>${esc(v.by||'Someone')}</b> vetoed ${esc(v.from)}!</p>`;
 else if(v.open)action=`<div class="veto-row" data-veto-until="${Number(v.until)||0}">${v.left?btn(`Veto <span class="veto-count">${Math.max(0,Math.ceil((v.until-Date.now())/1000))}</span>`,'veto','secondary veto-btn'):`<span class="veto-wait">Veto closes in <span class="veto-count">${Math.max(0,Math.ceil((v.until-Date.now())/1000))}</span></span>`}<span class="micro">${left}</span></div>`;
 return `<div class="veto-panel">${themeCard(s.theme)}${action}${v.open?'':`<p class="micro">${left}</p>`}</div>`;}setInterval(updateClock,250);
function offerRejoin(seat){app.innerHTML=`<div class="card"><h2>Welcome back</h2><p>You were in room <b>${esc(seat.code)}</b>${seat.name?` as <b>${esc(seat.name)}</b>`:''}.</p><button id="rejoin">Rejoin${seat.name?` as ${esc(seat.name)}`:''}</button><button id="fresh" class="ghost">Join as someone new</button></div>`;document.querySelector('#rejoin').onclick=()=>{auth={code:seat.code,token:seat.token};saveSeat(auth);app.innerHTML='<div class="card"><h2>Rejoining your room…</h2></div>';connect();};document.querySelector('#fresh').onclick=home;}
